html:
{# A formal grid: one row per signatory. Add or remove rows as you need. #}
<table class="rvs-grid">
  <thead><tr><th>{{ _("Capacity") }}</th><th>{{ _("Name", context="Report View") }}</th><th>{{ _("Signature", context="Report View") }}</th><th>{{ _("Date") }}</th></tr></thead>
  <tbody>
  {% for role in [_("Prepared by"), _("Reviewed by"), _("Approved by")] %}
    <tr><td>{{ role }}</td><td></td><td></td><td></td></tr>
  {% endfor %}
  </tbody>
</table>

css:
.rvs-grid{width:100%;border-collapse:collapse;table-layout:fixed}
.rvs-grid th,.rvs-grid td{border:1px solid var(--pp-tx,#1b1f1d);padding:2mm 3mm;text-align:start}
.rvs-grid th{background:var(--pp-head,#eef1ef);font-weight:700}
.rvs-grid td{height:10mm}
.rvs-grid th:first-child{width:28%}

.rvs-pair{display:grid;grid-template-columns:1fr 1fr;gap:8mm}
.rvs-pair section{border:1px solid #d5dbd8;border-radius:2mm;padding:2.2mm 3.5mm 3mm;break-inside:avoid}
.rvs-pair header{font-weight:700;padding-bottom:1.2mm;border-bottom:1.5px solid #1b1f1d}
.rvs-ln{display:flex;align-items:flex-end;gap:2mm;margin:3.2mm 0 0;color:#5b6560}
.rvs-ln span{white-space:nowrap}
.rvs-ln span::after{content:":"}
.rvs-ln i{flex:1;height:1em;border-bottom:1px dotted #8a948f}
.rvs-ln b{flex:1;color:#1b1f1d;font-weight:600}

.rvs-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6mm}
.rvs-steps section{break-inside:avoid}
.rvs-steps header{display:flex;align-items:center;gap:1.8mm;font-weight:700;padding-bottom:1.2mm;border-bottom:1.5px solid #1b1f1d}
.rvs-steps em{display:inline-grid;place-items:center;width:4.6mm;height:4.6mm;border-radius:50%;background:#1b1f1d;color:#fff;font-style:normal;font-size:.8em;font-weight:700}
.rvs-box{height:13mm;margin-top:2.5mm;border:1px dashed #b5bdb9;border-radius:1.5mm;display:flex;align-items:flex-end;padding:1mm 2mm;color:#8a948f;font-size:.85em}
.rvs-ln{display:flex;align-items:flex-end;gap:2mm;margin:2.8mm 0 0;color:#5b6560}
.rvs-ln span{white-space:nowrap}
.rvs-ln span::after{content:":"}
.rvs-ln i{flex:1;height:1em;border-bottom:1px dotted #8a948f}
.rvs-ln b{flex:1;color:#1b1f1d;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.rvs-stamped{display:grid;grid-template-columns:1fr 1fr 30mm;gap:7mm;align-items:center}
.rvs-stamped section{break-inside:avoid}
.rvs-stamped header{font-weight:700;padding-bottom:1.2mm;border-bottom:1.5px solid #1b1f1d}
.rvs-seal{width:28mm;height:28mm;border:1.5px dashed #8a948f;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1mm;text-align:center;color:#6b736f;padding:3mm;box-sizing:border-box}
.rvs-seal small{font-size:.8em;line-height:1.2}
.rvs-ln{display:flex;align-items:flex-end;gap:2mm;margin:3.2mm 0 0;color:#5b6560}
.rvs-ln span{white-space:nowrap}
.rvs-ln span::after{content:":"}
.rvs-ln i{flex:1;height:1em;border-bottom:1px dotted #8a948f}
.rvs-ln b{flex:1;color:#1b1f1d;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.rvs-ack{border:1px solid #d5dbd8;border-inline-start:3px solid #1b1f1d;border-radius:1.5mm;background:#f5f7f6;padding:2.5mm 4mm 3mm;break-inside:avoid}
.rvs-ack-t{margin:0;font-weight:600}
.rvs-ack-row{display:grid;grid-template-columns:1.3fr 1fr .8fr;gap:6mm}
.rvs-ln{display:flex;align-items:flex-end;gap:2mm;margin:4mm 0 0;color:#5b6560}
.rvs-ln span{white-space:nowrap}
.rvs-ln span::after{content:":"}
.rvs-ln i{flex:1;height:1em;border-bottom:1px dotted #8a948f}
